const log = { tool: 'client_snapshot', input: $json, ts: new Date().toISOString() };
console.log(JSON.stringify(log));
return $input.all();

const input = $json || {};
const user_id = String(input.user_id || '').trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(user_id)) throw new Error('user_id (UUID) é obrigatório');
const limit = Math.max(1, Math.min(500, +(input.limit) || 50));
let raw = input.filters;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { raw = null; } }
const filters = (raw && typeof raw === 'object') ? { ...raw } : {};
const vendedor = String(input.vendedor || '').trim();
if (vendedor) filters.vendedor = vendedor;
for (const k of Object.keys(filters)) { if (filters[k] === null || filters[k] === '') delete filters[k]; }
return [{ json: { user_id, limit, filters } }];

const params = $('Prepare params').first().json;
const rows = $input.all();
const firstErr = rows[0] && rows[0].json && rows[0].json.error;
if (firstErr) {
  return [{ json: { ok: false, data: null, error: String(firstErr.message || firstErr) } }];
}
const res = rows[0] && rows[0].json ? rows[0].json.result : null;
if (!res) {
  return [{ json: { ok: false, data: null, error: 'castor_snapshot_query nao retornou resultado' } }];
}
if (res.ok === false) {
  return [{ json: { ok: false, data: [], count: 0, error: res.error || 'consulta rejeitada' } }];
}
return [{ json: { ok: true, count: res.count, scope_applied: res.scope_applied, filters: params.filters, data: res.data || [], error: null } }];
